import {findProfile,profileMatches,recommend} from './profile-model.js';
import {research} from './profile-service.js';
import {escapeHTML as safe} from './search-model.js';
import {spots,at,finite} from './model.js';
import {escapeHTML as esc,parseCoordinates,normalizeResults,gridUsable,distanceKm} from './search-model.js';
const $=id=>document.getElementById(id),cache=new Map(),forecasts=new Map();let searchRun=0,forecastRun=0,active=null,data=null,chosen=null,busy=false,searchBusy=false,searchController,forecastController,profileController,localEvidence=null,researchBusy=false,researchError=false;
const fmt=(t,zone)=>new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(t*1000);
const value=(v,unit='',factor=1)=>finite(v)?(v*factor).toFixed(1)+unit:'Unavailable';
async function get(url,signal){const r=await fetch(url,{signal});if(!r.ok)throw Error('Provider unavailable');const d=await r.json();if(d.error)throw Error('Provider unavailable');return d;}
function curated(){forecastRun++;forecastController?.abort();active=null;profileController?.abort();$('worldPanel').hidden=true;$('curatedLayout').hidden=false;$('searchResults').hidden=true;$('curatedButton').classList.add('chosen');$('worldStatus').textContent='Curated SoCal spots use local profiles and personalized screening.';}
$('curatedButton').onclick=curated;
function selectCurated(i){curated();document.querySelector(`[data-spot="${i}"]`)?.click();$('details').scrollIntoView({behavior:'smooth'});}
function resultButton(label,sub,choose){const b=document.createElement('button');b.type='button';b.className='search-result';const title=document.createElement('strong');title.textContent=label;const detail=document.createElement('span');detail.textContent=sub;b.append(title,detail);b.onclick=choose;return b;}
async function search(e){e?.preventDefault();const q=$('beachQuery').value.trim();if(q.length<2){$('searchStatus').textContent='Enter at least two characters, or latitude, longitude.';return;}const run=++searchRun;searchController?.abort();searchController=new AbortController();const controller=searchController,timer=setTimeout(()=>controller.abort(),15000);searchBusy=true;$('searchSubmit').disabled=true;$('searchResults').hidden=false;$('resultsList').replaceChildren();$('searchStatus').textContent='Searching beaches and coastal places…';
const seedMatches=profileMatches(q);for(const p of seedMatches)$('resultsList').append(resultButton(p.name,`SOURCED PROFILE · ${p.region} · Personalized advice`,()=>select({...p,beach:true,kind:'Sourced surf spot'})));
const matches=spots.map((s,i)=>({s,i})).filter(({s})=>(s.name+' '+s.region).toLowerCase().includes(q.toLowerCase()));for(const {s,i} of matches)$('resultsList').append(resultButton(s.name,`CURATED · ${s.region} · Personalized advice`,()=>selectCurated(i)));
try{const coordinates=parseCoordinates(q);let results;if(coordinates){results=[{id:`coordinate-${coordinates.lat}-${coordinates.lon}`,name:'Selected coordinates',region:`${coordinates.lat}, ${coordinates.lon}`,kind:'Coordinates · confirm shoreline',...coordinates}];}else{if(/^-?[\d.]+\s*,\s*-?[\d.]+$/.test(q))throw Error('Coordinates must be latitude −90 to 90, longitude −180 to 180.');const key=q.toLowerCase();if(cache.has(key))results=cache.get(key);else{results=normalizeResults(await get('https://photon.komoot.io/api/?'+new URLSearchParams({q,limit:12,lang:'en'}),searchController.signal));cache.set(key,results);}}
if(run!==searchRun)return;for(const s of results)$('resultsList').append(resultButton(s.name,`${s.kind} · ${s.region} · ${s.lat.toFixed(3)}, ${s.lon.toFixed(3)}`,()=>select(s)));$('searchStatus').textContent=results.length||matches.length||seedMatches.length?'Choose a beach. We’ll look up local evidence and explain how it affects your recommendation.':'No matching beaches or places found. Try the beach name plus country, a nearby coastal town, or latitude, longitude.';
}catch(error){if(run!==searchRun)return;$('searchStatus').textContent=error.message.startsWith('Coordinates')?error.message:'Live search is unavailable. You can still select a sourced profile above, retry, or use coordinates.';}finally{clearTimeout(timer);if(run===searchRun){searchBusy=false;$('searchSubmit').disabled=false;}}}
$('beachSearch').onsubmit=search;$('beachQuery').oninput=()=>{if(searchBusy){searchRun++;searchController?.abort();searchBusy=false;$('searchSubmit').disabled=false;}$('searchResults').hidden=true;};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('beachQuery').value=b.dataset.example;search();});
async function select(spot,force=false){const run=++forecastRun;forecastController?.abort();forecastController=new AbortController();const controller=forecastController,timer=setTimeout(()=>controller.abort(),20000);const changed=active?.id!==spot.id;active=spot;if(changed||!localEvidence)loadEvidence(spot);data=null;chosen=null;busy=true;$('searchResults').hidden=true;$('worldPanel').hidden=false;$('curatedLayout').hidden=true;$('curatedButton').classList.remove('chosen');$('worldPanel').scrollIntoView({behavior:'smooth',block:'start'});render();
try{const stored=forecasts.get(spot.id);if(!force&&stored&&Date.now()-stored.fetched<15*60e3)data=stored;else{const base=new URLSearchParams({latitude:spot.lat,longitude:spot.lon,forecast_days:4,timeformat:'unixtime',timezone:'auto'});const profile=findProfile(spot);const tideParams=profile?new URLSearchParams({begin_date:new Date().toISOString().slice(0,10).replaceAll('-',''),end_date:new Date(Date.now()+4*86400e3).toISOString().slice(0,10).replaceAll('-',''),station:profile.station,product:'predictions',datum:'MLLW',time_zone:'gmt',interval:'h',units:'metric',format:'json'}):null;const results=await Promise.allSettled([get('https://marine-api.open-meteo.com/v1/marine?'+base+'&cell_selection=sea&hourly=wave_height,swell_wave_height,swell_wave_period,swell_wave_direction',controller.signal),get('https://api.open-meteo.com/v1/forecast?'+base+'&hourly=wind_speed_10m,wind_direction_10m,is_day&wind_speed_unit=kn',controller.signal),tideParams?get('https://api.tidesandcurrents.noaa.gov/api/prod/datagetter?'+tideParams,controller.signal):Promise.resolve(null)]);if(run!==forecastRun)return;const [marine,weather,tideData]=results.map(r=>r.status==='fulfilled'?r.value:null);data={marine,weather,tides:tideData?.predictions?.map(p=>({time:Date.parse(p.t.replace(' ','T')+'Z')/1000,value:Number(p.v)})),fetched:Date.now()};if(marine&&weather)forecasts.set(spot.id,data);}if(run!==forecastRun)return;const now=Date.now()/1000;const hours=(data.marine?.hourly?.time||data.weather?.hourly?.time||[]).filter(t=>t>=Math.floor(now/3600)*3600&&t<=now+48*3600);chosen=hours.find(t=>at(data.weather?.hourly,t,'is_day')===1)??hours[0]??null;data.hours=hours;
}catch{if(run!==forecastRun)return;data={fetched:Date.now(),hours:[]};}finally{clearTimeout(timer);if(run===forecastRun){busy=false;render();}}}
function render(){if(!active)return;const s=active,zone=data?.weather?.timezone||data?.marine?.timezone||'UTC',m=data?.marine,w=data?.weather,usable=gridUsable(s,m),stale=data&&Date.now()-data.fetched>30*60e3;const wave=k=>usable&&!stale?at(m?.hourly,chosen,k):null,wind=k=>!stale?at(w?.hourly,chosen,k):null;
$('worldStatus').textContent='Local evidence + live forecasts · Personalized, with stated uncertainty';$('worldContent').innerHTML=`<div class="world-heading"><div><span class="pill">${findProfile(active)?'SOURCED LOCAL PROFILE':'AUTOMATIC LOCAL LOOKUP'}</span><h2>${esc(s.name)}</h2><p>${esc(s.region)} · ${s.lat.toFixed(4)}, ${s.lon.toFixed(4)}</p></div><a class="map-link" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${s.lat}&mlon=${s.lon}#map=14/${s.lat}/${s.lon}">Confirm location on map ↗</a></div><div class="world-toolbar"><div><label for="worldHour">Forecast hour · ${esc(zone)}</label><select id="worldHour" ${busy||!data?.hours?.length?'disabled':''}>${data?.hours?.length?data.hours.map(t=>`<option value="${t}" ${t===chosen?'selected':''}>${esc(fmt(t,zone))}</option>`).join(''):'<option>'+(busy?'Loading forecast…':'No forecast hours available')+'</option>'}</select></div><button id="worldRefresh" class="refresh" ${busy?'disabled':''}>↻ Refresh forecasts</button></div><p class="world-notice" role="status">${busy?'Fetching live marine and wind forecasts…':!m||!w?'Some forecast data is unavailable. Refresh to retry.':!usable?'No nearby marine grid found. This may be inland or outside useful coastal coverage; marine values are withheld.':stale?'Forecast data is stale. Refresh before using it.':'Live offshore model data. Personalized advice below uses sourced context and experimental rules—not a validated surf-zone model.'}</p><div class="metrics"><div><small>Offshore total Hs</small><strong>${value(wave('wave_height'),' ft',3.28084)}</strong></div><div><small>Main swell · mean period</small><strong>${value(wave('swell_wave_height'),' ft',3.28084)} / ${value(wave('swell_wave_period'),' s')}</strong></div><div><small>Swell from</small><strong>${value(wave('swell_wave_direction'),'°')}</strong></div><div><small>Wind · direction from</small><strong>${value(wind('wind_speed_10m'),' kn')} / ${value(wind('wind_direction_10m'),'°')}</strong></div></div>${personalized(wave,wind,stale)}<p class="data-caption">${data?'Retrieved '+esc(fmt(data.fetched/1000,zone))+'. ':''}${m?`Marine grid ${m.latitude.toFixed(3)}, ${m.longitude.toFixed(3)} · ${distanceKm(s,{lat:m.latitude,lon:m.longitude}).toFixed(1)} km from selected point. `:''}A nearby grid does not prove a location is coastal or surfable. Values beyond 35 km are withheld. Confirm the beach on the map.</p>`;
$('worldHour').onchange=e=>{chosen=Number(e.target.value);render()};$('worldRefresh').onclick=()=>select(active,true);$('returnCurated').onclick=curated;$('researchAgain').onclick=()=>loadEvidence(active,true);for(const id of ['worldLevel','worldBoard'])$(id).onchange=e=>{const original=$(id==='worldLevel'?'level':'board');original.value=e.target.value;original.dispatchEvent(new Event('change'));render();};}
setInterval(()=>{if(active&&!busy)select(active);},15*60e3);
document.querySelectorAll('nav a[href="#science"],nav a[href="#recommendations"]').forEach(a=>a.addEventListener('click',curated));

async function loadEvidence(spot,force=false){
 profileController?.abort();const controller=new AbortController();profileController=controller;
 localEvidence=null;researchBusy=true;researchError=false;
 const timeout=setTimeout(()=>controller.abort(),14000);if(active)render();
 try{const result=await research(spot,{signal:controller.signal,force});if(profileController!==controller||active?.id!==spot.id)return;localEvidence=result;}
 catch{if(profileController!==controller||active?.id!==spot.id)return;const seed=findProfile(spot);if(seed)localEvidence={profile:{...seed,automatic:false},checks:['Live source lookup failed. Showing the dated researched profile only.'],partial:true};researchError=true;}
 finally{clearTimeout(timeout);if(profileController===controller){researchBusy=false;render();}}
}
function personalized(wave,wind,stale){
 const level=$('level').value,board=$('board').value,p=localEvidence?.profile;
 const c={height:wave('wave_height'),swell:wave('swell_wave_height'),period:wave('swell_wave_period'),direction:wave('swell_wave_direction'),wind:wind('wind_speed_10m'),windDirection:wind('wind_direction_10m'),day:wind('is_day'),tide:!stale?data?.tides?.find(t=>t.time===chosen)?.value:null,fetched:data?.fetched};
 const r=p?recommend(p,c,level,board):null;
 const controls=`<div class="personal-controls"><div><label for="worldLevel">Your experience</label><select id="worldLevel">${['beginner','intermediate','advanced'].map(x=>`<option value="${x}" ${x===level?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div><label for="worldBoard">Your board</label><select id="worldBoard">${Object.entries({fish:'5′10″ fish · 34 L',foam:'8′ foam board · 80 L',short:'6′ shortboard · 29 L'}).map(([v,l])=>`<option value="${v}" ${v===board?'selected':''}>${l}</option>`).join('')}</select></div></div><p class="data-caption">Example rider: 75 kg. Board volume, shape, fitness and control matter; length alone cannot determine fit.</p>`;
 const recommendation=r?`<div class="personal-call ${r.tone}"><div class="call-top"><span class="eyebrow">YOUR SESSION, EXPLAINED</span><span class="confidence">Recommendation confidence: ${r.confidence}</span></div><h3>${safe(r.title)}</h3><ul>${r.reasons.map(x=>`<li>${safe(x)}</li>`).join('')}</ul><div class="board"><div class="board-icon">◒</div><div><h4>${safe(r.boardTitle)}</h4><p>${safe(r.board)}</p></div></div><p class="data-caption">Lineup interpretation of the facts below + selected forecast. No on-site validation or safety guarantee.</p></div>`:`<p class="world-notice" role="status">${researchBusy?'Looking up local sources…':'Local lookup failed. Retry to get evidence-based advice; forecasts remain available.'}</p>`;
 const facts=p?`<div class="evidence-top"><div><span class="eyebrow">WHAT THIS IS BASED ON</span><h3>Local evidence and sources.</h3></div><span class="confidence">${p.automatic?'Automatic · not reviewed locally':'Researched · '+safe(p.reviewed)}</span></div><p class="data-caption">${safe(p.scope)} ${p.normal?`Shoreline normal ≈ ${p.normal}° is a map-based estimate (low confidence), used only for wind/swell orientation checks.`:''}</p><div class="evidence-grid">${p.facts.map(f=>`<article class="evidence-card"><div class="call-top"><strong>${safe(f.label)}</strong><span class="confidence">${safe(f.confidence)} confidence</span></div><p>${safe(f.text)}</p><a href="${safe(f.source)}" target="_blank" rel="noopener">${safe(f.publisher)} ↗</a></article>`).join('')||'<p>No specific local facts were found. Missing evidence stays unknown.</p>'}</div><div class="reasons world-reasons"><div class="reason"><span class="reason-num">TIDE CONTEXT</span><h4>${p.station?value(c.tide,' ft MLLW',3.28084):'No tide station connected'}</h4><p>${p.station?`${safe(p.stationName)}. Regional astronomical prediction, not water depth at the break. No calibrated local tide window.`:'A local tide window has not been established.'}</p>${p.station?`<a class="source-link" href="https://tidesandcurrents.noaa.gov/noaatidepredictions.html?id=${p.station}" target="_blank" rel="noopener">NOAA station ${p.station} ↗</a>`:''}</div><div class="reason"><span class="reason-num">STILL UNKNOWN</span><h4>Check at the beach</h4><ul>${(r?.unknowns||p.unknowns).map(x=>`<li>${safe(x)}</li>`).join('')}</ul>${p.water?`<a class="source-link" href="${safe(p.water)}" target="_blank" rel="noopener">Check official water quality / notices ↗</a>`:''}</div></div>`:'';
 const diagnostics=localEvidence?`<p class="data-caption">${localEvidence.retrieved?'Sources retrieved '+new Date(localEvidence.retrieved).toLocaleString()+'. ':''}${localEvidence.cached?'Saved evidence reused (up to 24 hours). ':''}${localEvidence.partial?'Some live sources failed. ':''}${localEvidence.checks.map(safe).join(' ')} Dated researched facts are not live re-verifications.</p>`:'';
 const wiki=p?.article?`<details class="evidence-notes"><summary>Matched background article: ${safe(p.article.title)}</summary><p>${safe(p.article.excerpt)}…</p><a href="${safe(p.article.source)}" target="_blank" rel="noopener">Wikipedia contributors · read full article ↗</a><p class="data-caption">Background only; may describe a larger area. Wikipedia text is available under CC BY-SA. Automated excerpts do not validate a break.</p></details>`:'';
 return controls+recommendation+facts+`<div class="evidence-actions"><button id="researchAgain" class="refresh" ${researchBusy?'disabled':''}>${researchBusy?'Looking up sources…':'↻ Refresh local evidence'}</button><button id="returnCurated" class="text-button">Explore curated SoCal spots →</button></div>`+diagnostics+wiki+`<details class="evidence-notes"><summary>How sources, confidence and recommendations work</summary><p>High fact confidence means an official source directly supports the stated fact; it does not mean today’s conditions are safe. Medium covers general local tendencies or a local operator’s account. Low covers automatic matching or map-based interpretation. Unknown means evidence is missing or does not establish the claim.</p><p>Rockaway, Swami’s and Tourmaline have dated researched profiles. Every selection also requests public Wikipedia records and, when a search result supplies an ID, its exact OpenStreetMap feature. Article matching requires both a matching name and coordinates within 1.5 km. This is a limited public-data lookup, not an exhaustive web search. Map sand describes the shore, not the underwater bottom. Automatic context never creates a positive beginner recommendation.</p><p>Recommendations are provisional and capped at Moderate confidence. Unknown bottom, missing tides, longer-period swell or automatic-only context cap confidence at Low. These labels are evidence categories, not probabilities. Thresholds are experimental: offshore Hs above 0.8 / 1.8 / 2.8 m for beginner / intermediate / advanced, wind ≥20 kn, and darkness exclude a window. Beginner mean period ≥13 s or wind >10 kn also excludes it. Reef + regional tide below 0.6 m MLLW triggers cautionary exclusion, not a clearance calculation. No optimal tide window is invented.</p><p>Deep-water energy density scales with Hs²; power also depends on energy period. Mean swell period is not energy period. We do not infer breaking height, precise power or a safety score from these inputs. Board advice is conditional on observed face shape. Sources are cached locally for 24 hours; Refresh retries live public records. It does not rewrite the researched profile.</p></details>`;
}
